type Product = { id: string; name: string; categoryId: string; active: boolean };

export async function listNextjsProducts(
  endpoint: string,
  categoryId: string,
  signal?: AbortSignal,
): Promise<Product[]> {
  const url = new URL("/api/products", endpoint);
  url.searchParams.set("category", categoryId);
  url.searchParams.set("active", "true");
  url.searchParams.set("sort", "name");
  url.searchParams.set("limit", "50");
  const response = await fetch(url, { signal: signal ?? AbortSignal.timeout(5_000) });
  if (!response.ok) throw new Error(`Product request failed: ${response.status}`);
  const result = (await response.json()) as { products: Product[] };
  return result.products;
}

